script:
// Avatar (ds-metrics §15 — CommentsAuthorAvatar): circle, el2 (≈ commentsAvatarPlaceholder) with initials (el9,
// bodySmallStrong; title from 56pt) under the remote image. Initials = first letters of up to two words of `name`,
// '@' stripped, uppercased, "?" when empty. The image placeholder is transparent so initials show until it loads.
param name: string = ""
param url: string = ""
param size: number = 40
let words = name.replace("@", "").split(" ").filter(w => w != "")
let initials = words.isEmpty ? "?" : words.slice(0, 2).map(w => w.substring(0, 1).upper()).join("")
